content.text:
    start = i
    while i < n and text[i] in DEC:
        i += 1
    digits = text[start:i]
    if not 1 <= len(digits) <= 15:
        raise Reject("syntax")
    if digits[0] == "0":
        raise Reject("syntax")
    return "tel:+" + digits, i


def parse_uri(text, pos):
    """Parse a sip or tel URI at text[pos]; return (normalized, end index)."""
    if pos + 4 <= len(text):
        scheme = text[pos:pos + 4].lower()
        if scheme == "sip:":
            return _parse_sip(text, pos + 4)
        if scheme == "tel:":
            return _parse_tel(text, pos + 4)
    raise Reject("syntax")


# ---------------------------------------------------------------------------
# address / display-name parsing
# ---------------------------------------------------------------------------

def _end_quoted(text, pos):
    """Return the index just past a quoted string starting at text[pos]."""
    n = len(text)
    i = pos + 1
    while i < n:
        ch = text[i]
        if ch == "\\":
            if i + 1 >= n:
                raise Reject("syntax")
            nxt = text[i + 1]
            if nxt != "\t" and not " " <= nxt <= "~":
                raise Reject("syntax")
            i += 2
        elif ch == '"':
            return i + 1
        else:
            i += 1
    raise Reject("syntax")


def _parse_tag_tail(text, pos):
    """Parse an optional ';tag=TOKEN' header parameter at text[pos]."""
    n = len(text)
    i = pos
    while i < n and text[i] in WSP:
        i += 1
    if i >= n:
        return None
    if text[i] != ";":
        raise Reject("syntax")
    i += 1
    while i < n and text[i] in WSP:
        i += 1
    start = i
    while i < n and text[i] in TOKEN_CHARS:
        i += 1
    if text[start:i].lower() != "tag":
        raise Reject("syntax")
    while i < n and text[i] in WSP:
        i += 1
    if i >= n or text[i] != "=":
        raise Reject("syntax")
    i += 1
    while i < n and text[i] in WSP:
        i += 1
    tstart = i
    while i < n and text[i] in TOKEN_CHARS:
        i += 1
    tag = text[tstart:i]
    if not 1 <= len(tag) <= 128:
        raise Reject("syntax")
    while i < n and text[i] in WSP:
        i += 1
    if i != n:
        raise Reject("syntax")
    return tag


def parse_address(text, allow_tag):
    """Parse exactly one address; return (normalized URI, tag or None)."""
    n = len(text)
    if not text:
        raise Reject("syntax")
    pos = 0
    if text[0] == '"':
        pos = _end_quoted(text, 0)
        i = pos
        while i < n and text[i] in WSP:
            i += 1
        if i >= n or text[i] != "<":
            raise Reject("syntax")
        pos = i + 1
    elif "<" in text:
        cut = text.index("<")
        if not RE_DISPLAY.match(text[:cut]):
            raise Reject("syntax")
        pos = cut + 1
    else:
        uri, end = parse_uri(text, 0)
        if allow_tag:
            return uri, _parse_tag_tail(text, end)
        if end != n:
            raise Reject("syntax")
        return uri, None

    i = pos
    while i < n and text[i] in WSP:
        i += 1
    uri, i = parse_uri(text, i)
    while i < n and text[i] in WSP:
        i += 1
    if i >= n or text[i] != ">":
        raise Reject("syntax")
    i += 1
    if allow_tag:
        return uri, _parse_tag_tail(text, i)
    if i != n:
        raise Reject("syntax")
    return uri, None


def split_address_list(text):
    """Split a comma separated address list, honouring quotes and brackets."""
    members = []
    cur = []
    depth = 0
    in_quote = False
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if in_quote:
            cur.append(ch)
            if ch == "\\":
                if i + 1 < n:
                    cur.append(text[i + 1])
                    i += 1
            elif ch == '"':
                in_quote = False
            i += 1
            continue
        if ch == '"':
            in_quote = True
            cur.append(ch)
        elif ch == "<":
            depth += 1
            cur.append(ch)
        elif ch == ">":
            if depth > 0:
                depth -= 1
            cur.append(ch)
        elif ch == "," and depth == 0:
            members.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
        i += 1
    members.append("".join(cur))
    return [member.strip(WSP) for member in members]


