class Parsed(object):
    __slots__ = ("method", "ruri", "furi", "ftag", "fanon", "turi", "ttag",
                 "callid", "cseq", "privacy", "ctype", "ppi", "rpid", "pai",
                 "body")


def parse_request(text):
    """Validate a whole request; return a Parsed object or raise Reject."""
    if len(text) > MAX_TEXT:
        raise Reject("syntax")
